package com.transiva.app;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.text.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class GlobalSearchActivity extends Activity{private static final String URL="https://transiva.my.id/server/customer_global_search.php?q=";private LinearLayout results;private Handler h=new Handler(Looper.getMainLooper());private Runnable pending;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(20),dp(16),dp(16));root.setBackgroundColor(Color.parseColor("#F6F9FE"));TextView t=new TextView(this);t.setText("Cari di Transiva");t.setTextSize(24);t.setTextColor(Color.parseColor("#0B3A78"));t.setTypeface(null,1);root.addView(t);EditText q=new EditText(this);q.setHint("Cari makanan, merchant, atau layanan...");root.addView(q,new LinearLayout.LayoutParams(-1,dp(56)));ScrollView sc=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);sc.addView(results);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){if(pending!=null)h.removeCallbacks(pending);pending=()->search(s.toString());h.postDelayed(pending,300);}public void afterTextChanged(Editable e){}});search("");}
private void search(String q){TransivaNetworkExecutor.execute(()->{try{HttpURLConnection c=CustomerApiClient.open(this,URL+URLEncoder.encode(q,"UTF-8"));c.setRequestMethod("GET");BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String l;while((l=br.readLine())!=null)s.append(l);JSONArray a=new JSONObject(s.toString()).optJSONArray("results");runOnUiThread(()->render(a));}catch(Exception e){}});}private void render(JSONArray a){results.removeAllViews();if(a==null)return;for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;Button b=new Button(this);String kind=x.optString("kind","");String name=x.optString("name","");b.setAllCaps(false);b.setText(("service".equals(kind)?"🚕 ":("merchant".equals(kind)?"🏪 ":"🍜 "))+name);b.setOnClickListener(v->open(kind,name));results.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));}}private void open(String kind,String name){if("service".equals(kind)){Class<?> c=TransRideActivity.class;if(name.equalsIgnoreCase("TransCar"))c=PassengerCarActivity.class;else if(name.equalsIgnoreCase("TransFood"))c=TransFoodActivity.class;else if(name.equalsIgnoreCase("TransShop"))c=TransShopActivity.class;startActivity(new Intent(this,c));return;}Intent i=new Intent(this,TransFoodActivity.class);i.putExtra("global_search_query",name);startActivity(i);}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
